import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const ROLES = ['Authorized User', 'Record Manager', 'Auditor', 'Admin'];
const roleDesc = {
  'Authorized User': 'View & download documents',
  'Record Manager':  'Upload & manage documents',
  'Auditor':         'View logs & generate reports',
  'Admin':           'Full system access'
};

export default function Register() {
  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'Authorized User' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { register } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await register(form.name, form.email, form.password, form.role);
      navigate('/dashboard');
    } catch (err) {
      setError(err.response?.data?.message || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '32px' }}>
      <div className="auth-card" style={{ maxWidth: '520px', width: '100%' }}>
        <div className="auth-card__header">
          <span className="eyebrow">Get started</span>
          <h2>Create Account</h2>
          <p>Join the Digital Records Management System</p>
        </div>

        {error && <div className="message message--error">⚠️ {error}</div>}

        <form onSubmit={handleSubmit}>
          <div className="grid grid--2">
            <div className="field">
              <label>Full Name</label>
              <input className="input" placeholder="Your full name" value={form.name}
                onChange={e => setForm({ ...form, name: e.target.value })} required />
            </div>
            <div className="field">
              <label>Email Address</label>
              <input className="input" type="email" placeholder="you@example.com" value={form.email}
                onChange={e => setForm({ ...form, email: e.target.value })} required />
            </div>
          </div>

          <div className="field">
            <label>Password</label>
            <input className="input" type="password" placeholder="Create a strong password" value={form.password}
              onChange={e => setForm({ ...form, password: e.target.value })} required />
          </div>

          <div className="field">
            <label>Select Role</label>
            <div className="grid grid--2" style={{ gap: '8px' }}>
              {ROLES.map(r => (
                <div key={r} onClick={() => setForm({ ...form, role: r })}
                  style={{ padding: '12px', border: `1.5px solid ${form.role === r ? '#4f46e5' : '#e2e8f0'}`, borderRadius: '10px', cursor: 'pointer', background: form.role === r ? '#ede9fe' : '#f8fafc', transition: 'all 0.15s' }}>
                  <div style={{ fontSize: '13px', fontWeight: '600', color: form.role === r ? '#4f46e5' : '#1e293b' }}>{r}</div>
                  <div style={{ fontSize: '11px', color: '#94a3b8', marginTop: '2px' }}>{roleDesc[r]}</div>
                </div>
              ))}
            </div>
          </div>

          <button type="submit" className="button button--primary button--full"
            style={{ padding: '12px', fontSize: '15px', marginTop: '4px' }} disabled={loading}>
            {loading ? '⏳ Creating account...' : '→  Create Account'}
          </button>
        </form>

        <p className="auth-footer">Already have an account? <Link to="/login">Sign in</Link></p>
      </div>
    </div>
  );
}
